mapper.select:
SELECT 
FROM hot_item
WHERE deleted = 0
  AND status = 1

  AND source = #{query.source}


  AND category = #{query.category}


  AND trend = #{query.trend}


  AND (title LIKE CONCAT('%', #{query.keyword}, '%')
       OR description LIKE CONCAT('%', #{query.keyword}, '%'))



    ORDER BY `rank` ASC, updated_at DESC


    ORDER BY `rank` ASC, hot_value DESC, updated_at DESC


    ORDER BY hot_value DESC, updated_at DESC


LIMIT #{query.limit}

SELECT 
FROM hot_item
WHERE category = #{category}
  AND id != #{excludeId}
  AND deleted = 0
  AND status = 1
ORDER BY hot_value DESC, updated_at DESC
LIMIT #{limit}

SELECT 
FROM hot_item
WHERE source = #{source}
  AND source_item_key = #{sourceItemKey}
  AND deleted = 0
LIMIT 1
